const userId = String($json.userId ?? '').trim();
const altText = String($json.altText ?? '').trim();
const raw = $json.contentsJson;

if (!/^U[0-9a-f]{32}$/.test(userId)) {
  throw new Error(`Invalid LINE userId: "${userId}". It must be U followed by 32 hex characters. Set it in the "LINE settings" node of the parent workflow.`);
}
if (!altText || altText.length > 400) {
  throw new Error('altText is required and must be 1-400 characters. It is the preview text shown where Flex cannot render.');
}

// Models often wrap JSON in a markdown fence, and sometimes return an object
// even though the tool schema asks for a string.
let contents;
if (raw && typeof raw === 'object') {
  contents = raw;
} else {
  let text = String(raw ?? '').trim();
  text = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  if (!text) {
    throw new Error('contentsJson is empty. Provide a LINE Flex container as JSON.');
  }
  try {
    contents = JSON.parse(text);
  } catch (e) {
    throw new Error(`contentsJson is not valid JSON (${e.message}). Return the Flex container as raw JSON only - no markdown fence, no trailing comma, all strings double-quoted.`);
  }
}

if (!contents || typeof contents !== 'object' || Array.isArray(contents)) {
  throw new Error('contentsJson must be a JSON object: the Flex container itself.');
}

// Accept a whole message object and unwrap it - a common model mistake.
if (contents.type === 'flex' && contents.contents) {
  contents = contents.contents;
}

if (contents.type !== 'bubble' && contents.type !== 'carousel') {
  throw new Error(`Flex container type must be "bubble" or "carousel", got ${JSON.stringify(contents.type)}. Send the container only, not the whole message object.`);
}
if (contents.type === 'carousel') {
  if (!Array.isArray(contents.contents) || contents.contents.length < 1) {
    throw new Error('A carousel needs a non-empty "contents" array of bubbles.');
  }
  if (contents.contents.length > 12) {
    throw new Error(`A carousel accepts at most 12 bubbles, got ${contents.contents.length}.`);
  }
}

return { json: { userId, message: { type: 'flex', altText, contents } } };
